/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(tableStr(VendTable))]
final class AVAVendTableDbt_Extension
{
}

Method.Source:
/// <summary>
/// Returns the email of the primary contact or from contact information if not defined
/// </summary>
/// <returns>Email</returns>
public Email avaPrimaryOrContactInformationEmail()
{
    Email avaMail = this.ContactPerson().email();

    if(avaMail == '')
    {
        avaMail = this.email();
    }

    return avaMail;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_locationRoleType">_locationRoleType</param>
/// <returns>avaName</returns>
public LogisticsInvoiceName avaName(LogisticsLocationRoleType _locationRoleType = LogisticsLocationRoleType::Business)
{
    LogisticsInvoiceName avaNameLoc = this.name();

    var location = LogisticsLocationDefault::findSimpleDefault(this,
        LogisticsLocationRole::findBytype(_locationRoleType));

    if (location)
    {
        LogisticsPostalAddress logisticsPostalAddressLoc = LogisticsPostalAddress::findByLocation(location.RecId);

        if(logisticsPostalAddressLoc.NDXLogisticsLocationName1
            || logisticsPostalAddressLoc.NDXLogisticsLocationName2
            || logisticsPostalAddressLoc.NDXLogisticsLocationName3)
        {
            avaNameLoc = '';
        }

        if(logisticsPostalAddressLoc.NDXLogisticsLocationName1)
        {
            avaNameLoc = logisticsPostalAddressLoc.NDXLogisticsLocationName1;
        }

        if(logisticsPostalAddressLoc.NDXLogisticsLocationName2)
        {
            if(avaNameLoc != '')
            {
                avaNameLoc += '\n';
            }

            avaNameLoc += logisticsPostalAddressLoc.NDXLogisticsLocationName2;
        }

        if(logisticsPostalAddressLoc.NDXLogisticsLocationName3)
        {
            if(avaNameLoc != '')
            {
                avaNameLoc += '\n';
            }

            avaNameLoc += logisticsPostalAddressLoc.NDXLogisticsLocationName3;
        }
    }

    return avaNameLoc;
}
